"""Public staging and generated bytes, separately from search relevance."""
import io
import subprocess
import tarfile
import json
from pathlib import Path
import shutil
import sys
import tempfile
import unittest
from unittest.mock import patch

ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT/'tools'))
import site_release as site
import search

class PublicSearchTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.temp=tempfile.TemporaryDirectory();cls.output=Path(cls.temp.name)/'site'
        site.package(ROOT,cls.output,public=True)
    @classmethod
    def tearDownClass(cls):cls.temp.cleanup()

    def test_public_search_identity_and_closed_urls(self):
        self.assertEqual(search.check(ROOT,self.output),[])
        docs=site.read_json(self.output/'search/documents.json')['documents']
        self.assertEqual(len(docs),15)
        self.assertEqual(sum(d['scope']=='atlas' for d in docs),12)
        hidden,_=site.public_projection.private_paths(ROOT)
        self.assertFalse(hidden & {d['id'] for d in docs})
        self.assertFalse((self.output/'search/manifest.json').exists())
        self.assertFalse((self.output/'search/pagefind/pagefind-ui.js').exists())

    def test_actual_text_excludes_navigation_footer_rail_cta_and_sources(self):
        docs,bodies=search.documents(ROOT,self.output)
        body=bodies['research:private-equity']
        self.assertIn('Deal Sourcing',body);self.assertIn('Carried Interest',body)
        self.assertNotIn('مشاهده حوزه',body);self.assertNotIn('از مفهوم تا تصمیم',body)
        synthetic='<article><p>APPROVED</p><aside>RAIL_SENTINEL</aside><nav>NAV_SENTINEL</nav><div class="cta"><h3>CTA_SENTINEL</h3></div><details class="research-bibliography">SOURCE_SENTINEL</details><footer>FOOTER_SENTINEL</footer></article>'
        text=search.Tree(synthetic).root.text()
        self.assertIn('APPROVED',text)
        for marker in ('RAIL','NAV','CTA','SOURCE','FOOTER'):self.assertNotIn(marker+'_SENTINEL',text)

    def test_registry_excludes_unpublished_research_without_touching_entity_status(self):
        original=search.read
        def registry(path):
            data=original(path)
            if path==ROOT/'research/index.json':
                data=json.loads(json.dumps(data));data['research'][0]['status']='REVIEW'
            return data
        with patch.object(search,'read',side_effect=registry):
            docs,bodies=search.documents(ROOT,self.output)
        self.assertNotIn('research:private-capital',{d['id'] for d in docs})
        self.assertIn('concept:private-capital',{d['id'] for d in docs})

    def test_corrupt_metadata_or_engine_bytes_fail_public_checks(self):
        with tempfile.TemporaryDirectory() as temp:
            output=Path(temp)/'site';shutil.copytree(self.output,output)
            p=output/'search/documents.json';data=site.read_json(p)
            data['documents'][0]['id']='project:dadman';p.write_text(json.dumps(data),encoding='utf-8')
            self.assertTrue(search.check(ROOT,output))
            with self.assertRaisesRegex(ValueError,'Artifact bytes differ'):
                site.check_artifact(ROOT,output,public=True)
            shutil.copyfile(self.output/'search/documents.json',p)
            fragment=next((output/'search/pagefind/fragment').glob('*'));fragment.write_bytes(fragment.read_bytes()+b'TAMPERED')
            with self.assertRaisesRegex(ValueError,'Artifact bytes differ'):
                site.check_artifact(ROOT,output,public=True)

    def test_approved_article_can_match_a_private_topic_without_entity_leak(self):
        docs,bodies=search.documents(ROOT,self.output)
        self.assertIn('اجزای قراردادی',bodies['research:private-capital'])
        self.assertNotIn('project:dadman',{d['id'] for d in docs})

    def test_previous_main_public_bundle_remains_recoverable(self):
        # Actual pre-search source tree, not a fabricated version flag.
        archive=subprocess.check_output(['git','archive','e9edde57303ad3de573da68a1ba29817b04b6936'],cwd=ROOT)
        with tempfile.TemporaryDirectory() as temp:
            historical=Path(temp)/'source';historical.mkdir()
            with tarfile.open(fileobj=io.BytesIO(archive)) as tar:tar.extractall(historical,filter='data')
            output=Path(temp)/'site';site.package(historical,output,public=True)
            self.assertFalse((output/'search').exists())
            import recovery
            result=recovery.publication(historical,output,current_root=ROOT)
            self.assertGreater(result['files'],0)

    def test_generated_homes_use_valid_curation_and_all_published_articles(self):
        research=(self.output/'articles.html').read_text(encoding='utf-8')
        atlas=(self.output/'atlas/index.html').read_text(encoding='utf-8')
        for r in site.read_json(ROOT/'research/index.json')['research']:
            if r['status']=='PUBLISHED':self.assertIn(r['url'],research)
        self.assertNotIn('در حال توسعه',research)
        self.assertNotIn('capital-transactions',atlas)
        self.assertEqual(atlas.count('class="discovery-path"'),3)
        self.assertNotIn('KAAVOSH_',atlas+research)
        self.assertLess(atlas.index('سرمایه خصوصی</h3>'),atlas.index('سرمایه رشد</h3>'))

if __name__=='__main__':unittest.main()
